const tabId = 2126149062;
const cardDetails = await browserjs(tabId, () => {
  const el = Array.from(document.querySelectorAll('*')).find(e => e.textContent && e.textContent.includes('Special Education Interrelated Teacher Barnett Shoals') && e.children.length === 0);
  if (!el) return { found: false };
  let curr = el;
  const path = [];
  while (curr && curr !== document.body) {
    path.push({
      tagName: curr.tagName,
      className: curr.className,
      id: curr.id,
      clickable: curr.onclick !== null || curr.getAttribute('role') === 'button' || curr.tagName === 'A'
    });
    curr = curr.parentElement;
  }
  return { found: true, text: el.textContent, path };
});
console.log(cardDetails);

